#pragma once

// DLIB: a compiled DScript library (dsc --lib), linked into programs by dsc (#import(<name>)).
//
// It holds the library's code and data (an image assembled at address 0, like a DRX), what is
// needed to put it anywhere and to connect it to the program and to other libraries, and the
// DScript declarations of what it offers (its interface, generated by the compiler):
//   image          the code and data, assembled at 0
//   relocations    offsets (in the image) of 32-bit addresses inside the image
//   imports        offsets of 32-bit addresses of symbols of other libraries, and their names
//   exports        the symbols (labels and data) of the library: name -> offset in the image
//   init           the offset of the routine that initializes its globals (called before main)
//   dependencies   the libraries it imports, as written in its #import(...)s
//   interface      DScript source: the declarations (subs without bodies, structs, constants,
//                  enums, aliases, globals; inline subs with their bodies)
//   lines          interface line -> where it comes from (file relative to the library, line,
//                  column delta), so that errors, hover and go to definition point at the
//                  library's sources
//   debug          (optional) the library's disassembly for the debugger, as the assembler
//                  saves it (.dds entries: address, size, text; addresses from 0): dsc puts it
//                  in the program's disassembly, at the library's address
//
// File layout (big endian): 'D' 'L' 'B' '1', then every part in the order above: counts (u32),
// numbers (u32), strings (u32 length, then the bytes), byte arrays (u32 length, then the bytes).

#include <cstdint>
#include <vector>
#include <string>

namespace dragon
{
	namespace dlib
	{
		inline constexpr uint32_t Magic = 0x444C4231;	// "DLB1"

		struct Import { uint32_t offset { 0 }; std::string symbol; };
		struct Export { std::string symbol; uint32_t offset { 0 }; };
		struct LineInfo { uint32_t line { 0 }; std::string file; uint32_t sourceLine { 0 }; int32_t columnDelta { 0 }; };
		struct DebugEntry { uint32_t address { 0 }; uint16_t size { 0 }; std::string text; };

		struct Library
		{
			std::vector<uint8_t> image;
			std::vector<uint32_t> relocations;
			std::vector<Import> imports;
			std::vector<Export> exports;
			uint32_t init { 0 };
			std::vector<std::string> dependencies;
			std::string interface;
			std::vector<LineInfo> lines;
			std::vector<DebugEntry> debug;
		};

		namespace detail
		{
			struct Writer
			{
				std::vector<uint8_t> out;
				void u32(uint32_t v) { for (int i = 3; i >= 0; i--) out.push_back((uint8_t)(v >> (8 * i))); }
				void bytes(const uint8_t* p, size_t n) { u32((uint32_t)n); out.insert(out.end(), p, p + n); }
				void str(const std::string& s) { bytes((const uint8_t*)s.data(), s.size()); }
			};
			struct Reader
			{
				const std::vector<uint8_t>& in;
				size_t pos { 0 };
				bool ok { true };
				uint32_t u32(void)
				{
					if (pos + 4 > in.size()) { ok = false; return 0; }
					uint32_t v = ((uint32_t)in[pos] << 24) | ((uint32_t)in[pos + 1] << 16) | ((uint32_t)in[pos + 2] << 8) | in[pos + 3];
					pos += 4;
					return v;
				}
				std::vector<uint8_t> bytes(void)
				{
					const uint32_t n = u32();
					if (!ok || pos + n > in.size()) { ok = false; return {}; }
					std::vector<uint8_t> v(in.begin() + pos, in.begin() + pos + n);
					pos += n;
					return v;
				}
				std::string str(void) { std::vector<uint8_t> v = bytes(); return std::string(v.begin(), v.end()); }
				uint32_t count(void) { const uint32_t n = u32(); if (n > in.size()) ok = false; return ok ? n : 0; }
			};
		}

		inline bool isDLIB(const std::vector<uint8_t>& file)
		{
			return file.size() >= 4 && (((uint32_t)file[0] << 24) | ((uint32_t)file[1] << 16) | ((uint32_t)file[2] << 8) | file[3]) == Magic;
		}

		inline std::vector<uint8_t> write(const Library& lib)
		{
			detail::Writer w;
			w.u32(Magic);
			w.bytes(lib.image.data(), lib.image.size());
			w.u32((uint32_t)lib.relocations.size());
			for (uint32_t r : lib.relocations)
				w.u32(r);
			w.u32((uint32_t)lib.imports.size());
			for (const Import& i : lib.imports)
			{
				w.u32(i.offset);
				w.str(i.symbol);
			}
			w.u32((uint32_t)lib.exports.size());
			for (const Export& e : lib.exports)
			{
				w.str(e.symbol);
				w.u32(e.offset);
			}
			w.u32(lib.init);
			w.u32((uint32_t)lib.dependencies.size());
			for (const std::string& d : lib.dependencies)
				w.str(d);
			w.str(lib.interface);
			w.u32((uint32_t)lib.lines.size());
			for (const LineInfo& l : lib.lines)
			{
				w.u32(l.line);
				w.str(l.file);
				w.u32(l.sourceLine);
				w.u32((uint32_t)l.columnDelta);
			}
			w.u32((uint32_t)lib.debug.size());
			for (const DebugEntry& e : lib.debug)
			{
				w.u32(e.address);
				w.u32(e.size);
				w.str(e.text);
			}
			return w.out;
		}

		// false (with a message) if the file is not a valid DLIB.
		inline bool read(const std::vector<uint8_t>& file, Library& lib, std::string& message)
		{
			if (!isDLIB(file))
			{
				message = "not a DScript library (.dlib)";
				return false;
			}
			detail::Reader r { file, 4 };
			lib = Library();
			lib.image = r.bytes();
			for (uint32_t i = 0, n = r.count(); i < n && r.ok; i++)
				lib.relocations.push_back(r.u32());
			for (uint32_t i = 0, n = r.count(); i < n && r.ok; i++)
			{
				Import imp;
				imp.offset = r.u32();
				imp.symbol = r.str();
				lib.imports.push_back(imp);
			}
			for (uint32_t i = 0, n = r.count(); i < n && r.ok; i++)
			{
				Export e;
				e.symbol = r.str();
				e.offset = r.u32();
				lib.exports.push_back(e);
			}
			lib.init = r.u32();
			for (uint32_t i = 0, n = r.count(); i < n && r.ok; i++)
				lib.dependencies.push_back(r.str());
			lib.interface = r.str();
			for (uint32_t i = 0, n = r.count(); i < n && r.ok; i++)
			{
				LineInfo l;
				l.line = r.u32();
				l.file = r.str();
				l.sourceLine = r.u32();
				l.columnDelta = (int32_t)r.u32();
				lib.lines.push_back(l);
			}
			if (r.ok && r.pos < file.size())
			{
				for (uint32_t i = 0, n = r.count(); i < n && r.ok; i++)
				{
					DebugEntry e;
					e.address = r.u32();
					e.size = (uint16_t)r.u32();
					e.text = r.str();
					lib.debug.push_back(e);
				}
			}
			if (!r.ok)
			{
				message = "truncated or damaged DScript library";
				return false;
			}
			for (uint32_t off : lib.relocations)
			{
				if ((uint64_t)off + 4 > lib.image.size())
				{
					message = "relocation outside of the library's image";
					return false;
				}
			}
			for (const Import& i : lib.imports)
			{
				if ((uint64_t)i.offset + 4 > lib.image.size())
				{
					message = "import outside of the library's image";
					return false;
				}
			}
			return true;
		}
	}
}
